   103	function normalizeResourceIdentifier(
   104	  value: string,
   105	  environment: AuthEnvironment,
   106	  applicationId: string,
   107	) {
   108	  const candidate =
   109	    value || new URL(`/api/resources/${applicationId}`, environment.BETTER_AUTH_URL).toString();
   110	  let parsed: URL;
   111	  try {
   112	    parsed = new URL(candidate);
   113	  } catch {
   114	    throw new ApiError(400);
   115	  }
   116	  if (
   117	    !["http:", "https:"].includes(parsed.protocol) ||
   118	    parsed.username ||
   119	    parsed.password ||
   120	    parsed.hash
   121	  ) {
