   359	export async function createApplication(
   360	  environment: AuthEnvironment,
   361	  actor: Actor,
   362	  body: ApplicationCreateBody,
   363	  request: Request,
   364	) {
   365	  await enforceRateLimit(environment, request, "application-create", 60, 60);
   366	  const database = createDb(environment.DB);
   367	  const name = normalizeName(body.name);
   368	  const description = normalizeDescription(body.description);
   369	  const ownership = await resolveActiveOwner(database, body);
   370	  const applicationId = `application_${crypto.randomUUID()}`;
   371	  const resourceIdentifier = normalizeResourceIdentifier(
   372	    body.resourceIdentifier ?? "",
   373	    environment,
   374	    applicationId,
   375	  );
   376	  const existingResource = await database
   377	    .select({ id: oauthResource.id })
   378	    .from(oauthResource)
   379	    .where(eq(oauthResource.identifier, resourceIdentifier))
   380	    .get();
   381	  if (existingResource) throw new ApiError(409);
   382	
   383	  const now = Date.now();
   384	  await database.batch([
   385	    database.insert(applications).values({
   386	      id: applicationId,
   387	      name,
   388	      description,
   389	      status: "active",
   390	      disabledAt: null,
   391	      ownerUserPrincipalId: ownership.ownerUserPrincipalId,
   392	      ownerTeamId: ownership.ownerTeamId,
   393	      authzVersion: 1,
   394	      createdAt: now,
   395	      updatedAt: now,
   396	    }),
   397	    database.insert(oauthResource).values({
   398	      id: `resource_${crypto.randomUUID()}`,
   399	      identifier: resourceIdentifier,
   400	      name,
   401	      accessTokenTtl: 3600,
   402	      refreshTokenTtl: null,
   403	      signingAlgorithm: null,
   404	      signingKeyId: null,
   405	      allowedScopes: [...SUPPORTED_SCOPES],
   406	      customClaims: {},
   407	      dpopBoundAccessTokensRequired: false,
   408	      disabled: false,
   409	      createdAt: new Date(now),
   410	      updatedAt: new Date(now),
   411	      policyVersion: 1,
   412	      metadata: null,
   413	    }),
   414	    database.insert(applicationResources).values({
   415	      applicationId,
   416	      resourceIdentifier,
   417	      createdAt: now,
   418	    }),
   419	    auditStatement(
   420	      database,
   421	      `application:created:${applicationId}`,
   422	      "application.created",
   423	      actor.principalId,
   424	      null,
   425	      null,
   426	      { applicationId, name, owner: ownership.owner, resourceIdentifier },
   427	      now,
   428	    ),
   429	    outboxStatement(
   430	      database,
   431	      `application:created:outbox:${applicationId}`,
   432	      "application.created",
   433	      "application",
   434	      applicationId,
   435	      { applicationId, name, resourceIdentifier },
   436	      now,
   437	    ),
   438	  ]);
   439	  return toApplication(database, await readApplicationRow(database, applicationId));
   440	}
