   442	export async function updateApplication(
   443	  environment: AuthEnvironment,
   444	  actor: Actor,
   445	  applicationId: string,
   446	  body: ApplicationUpdateBody,
   447	  request: Request,
   448	) {
   449	  await enforceRateLimit(environment, request, "application-update", 60, 60);
   450	  if (body.name === undefined && body.description === undefined) throw new ApiError(400);
   451	  const database = createDb(environment.DB);
   452	  const current = await readApplicationRow(database, applicationId);
   453	  if (current.status !== "active") throw new ApiError(404);
   454	  const name = body.name === undefined ? current.name : normalizeName(body.name);
   455	  const description =
   456	    body.description === undefined ? current.description : normalizeDescription(body.description);
   457	  const now = Date.now();
   458	  const changed = database
   459	    .update(applications)
   460	    .set({ name, description, updatedAt: now })
   461	    .where(and(eq(applications.id, applicationId), eq(applications.status, "active")))
   462	    .returning({ id: applications.id });
   463	  const resourceChanged = database
   464	    .update(oauthResource)
   465	    .set({ name, updatedAt: new Date(now) })
   466	    .where(eq(oauthResource.identifier, current.resourceIdentifier));
   467	  const updated = database
   468	    .select({ value: applications.id })
   469	    .from(applications)
   470	    .where(and(eq(applications.id, applicationId), eq(applications.updatedAt, now)));
   471	  const result = await database.batch([
   472	    changed,
   473	    resourceChanged,
   474	    auditStatementWhen(
   475	      database,
   476	      `application:updated:${applicationId}:${now}`,
   477	      "application.updated",
   478	      actor.principalId,
   479	      null,
   480	      null,
   481	      { applicationId, name, description },
   482	      now,
   483	      updated,
