   489	      "application",
   490	      applicationId,
   491	      { applicationId, name, description },
   492	      now,
   493	      updated,
   494	    ),
   495	  ]);
   496	  if (!result[0]?.length) throw new ApiError(409);
   497	  return toApplication(database, await readApplicationRow(database, applicationId));
   498	}
