233	async function authorizeWithPkce(clientId: string, cookie: string) {
234	  const verifier = `verifier-${crypto.randomUUID()}-${crypto.randomUUID()}`;
235	  const challenge = await sha256Base64Url(verifier);
236	  const state = crypto.randomUUID();
237	  const redirectUri = `${origin}/oauth/callback`;
238	  const params = new URLSearchParams({
239	    client_id: clientId,
240	    code_challenge: challenge,
241	    code_challenge_method: "S256",
242	    redirect_uri: redirectUri,
243	    response_type: "code",
244	    resource: resourceIdentifier,
245	    scope: "openid profile email",
246	    state,
247	  });
248	  const response = await SELF.fetch(`${origin}/api/auth/oauth2/authorize?${params}`, {
249	    headers: { cookie },
250	    redirect: "manual",
251	  });
252	  const location = response.headers.get("location");
253	
254	  expect(response.status).toBe(302);
255	  expect(location).toBeTruthy();
256	
257	  const callback = new URL(location ?? redirectUri);
258	  expect(callback.origin).toBe(origin);
259	  expect(callback.searchParams.get("state")).toBe(state);
260	  expect(callback.searchParams.get("code")).toBeTruthy();
261	
262	  return {
263	    code: callback.searchParams.get("code") ?? "",
264	    redirectUri,
265	    verifier,
266	  };
267	}
